package com.ramanan.fit.anim

import android.content.Context
import org.json.JSONObject

/**
 * Loads the bundled stick-figure animations (assets/poses/poses.json, generated by
 * tools/make_poses.py). Each exercise is a loop of evenly spaced frames; [sample]
 * linearly interpolates between them so motion is smooth at any frame rate.
 */
class PoseAnimation(
    val view: String,
    val loopMs: Long,
    private val frames: List<FloatArray>,
    private val far: IntArray,
) {
    val jointCount: Int get() = frames[0].size / 2

    /** Joint coordinates (x0,y0,x1,y1,…) at [timeMs] into the loop. Reuses [out]. */
    fun sample(timeMs: Long, out: FloatArray): Int {
        val n = frames.size
        val pos = ((timeMs % loopMs + loopMs) % loopMs).toFloat() / loopMs * n
        val i0 = pos.toInt() % n
        val i1 = (i0 + 1) % n
        val f = pos - pos.toInt()
        val a = frames[i0]; val b = frames[i1]
        for (k in a.indices) out[k] = a[k] + (b[k] - a[k]) * f
        return if (f < 0.5f) far[i0] else far[i1]
    }
}

object PoseLibrary {
    @Volatile private var cache: Map<String, PoseAnimation>? = null
    var canvasW = 100f; private set
    var canvasH = 120f; private set
    var groundY = 112f; private set
    var headRadius = 6f; private set

    // Joint indices — must match JOINTS in tools/make_poses.py
    const val HEAD = 0; const val NOSE = 1; const val NECK = 2
    const val SH_A = 3; const val SH_B = 4; const val EL_A = 5; const val EL_B = 6
    const val HA_A = 7; const val HA_B = 8; const val PELVIS = 9
    const val HIP_A = 10; const val HIP_B = 11; const val KN_A = 12; const val KN_B = 13
    const val AN_A = 14; const val AN_B = 15; const val FT_A = 16; const val FT_B = 17

    fun get(context: Context, id: String): PoseAnimation? = load(context)[id]

    fun load(context: Context): Map<String, PoseAnimation> {
        cache?.let { return it }
        synchronized(this) {
            cache?.let { return it }
            val result = try {
                val text = context.assets.open("poses/poses.json").bufferedReader().use { it.readText() }
                val root = JSONObject(text)
                val canvas = root.getJSONArray("canvas")
                canvasW = canvas.getDouble(0).toFloat()
                canvasH = canvas.getDouble(1).toFloat()
                groundY = root.getDouble("ground").toFloat()
                headRadius = root.getDouble("headRadius").toFloat()
                val exs = root.getJSONObject("exercises")
                val map = HashMap<String, PoseAnimation>()
                for (key in exs.keys()) {
                    val ex = exs.getJSONObject(key)
                    val fr = ex.getJSONArray("frames")
                    val frames = ArrayList<FloatArray>(fr.length())
                    val far = IntArray(fr.length())
                    for (i in 0 until fr.length()) {
                        val o = fr.getJSONObject(i)
                        val p = o.getJSONArray("p")
                        frames += FloatArray(p.length()) { p.getDouble(it).toFloat() }
                        far[i] = o.optInt("far", 0)
                    }
                    map[key] = PoseAnimation(ex.getString("view"), ex.getLong("loopMs"), frames, far)
                }
                map
            } catch (_: Exception) {
                emptyMap()
            }
            cache = result
            return result
        }
    }
}
